        Hooks to dehydrate types (dict from type (class) to dehydration
        function). Dehydration functions receive the value and returns an
        object of type understood by packstream.
    :param hydration_hooks:
        Hooks to hydrate types (mapping from type (class) to
        dehydration function). Dehydration functions receive the value of
        type understood by packstream and are free to return anything.
    :param handlers: handler functions passed into the returned Response object
    :return: Response object
    """
    if mode is None:
        mode = "WRITE"
    if bookmarks is None:
        bookmarks = []
    if metadata is None:
        metadata = {}
    if timeout is None:
        timeout = 0
    if db is None:
        db = ""
    if imp_user is None:
        imp_user = ""
    if dehydration_hooks is None:
        dehydration_hooks = {}
    if hydration_hooks is None:
        hydration_hooks = {}
    if not isinstance(mode, str):
        raise TypeError("Mode must be a string")
    if not isinstance(bookmarks, (list, tuple)):
        raise TypeError("Bookmarks must be a list or tuple")
    if not isinstance(metadata, dict):
        raise TypeError("Metadata must be a dictionary")
    if not isinstance(timeout, (int, float)):
        raise TypeError("Timeout must be a number")
    if not isinstance(db, str):
        raise TypeError("Database must be a string")
    if not isinstance(imp_user, str):
        raise TypeError("Impersonated user must be a string")
    if not isinstance(dehydration_hooks, dict):
        raise TypeError("Dehydration hooks must be a dictionary")
    if not isinstance(hydration_hooks, dict):
        raise TypeError("Hydration hooks must be a dictionary")
    if not all(isinstance(key, str) for key in dehydration_hooks.keys()):
        raise TypeError("Dehydration hook keys must be strings")
    if not all(callable(value) for value in dehydration_hooks.values()):
        raise TypeError("Dehydration hook values must be callable")
    if not all(isinstance(key, str) for key in hydration_hooks.keys()):
        raise TypeError("Hydration hook keys must be strings")
    if not all(callable(value) for value in hydration_hooks.values()):
        raise TypeError("Hydration hook values must be callable")
    if not all(isinstance(key, str) for key in handlers.keys()):
        raise TypeError("Handler keys must be strings")
    if not all(callable(value) for value in handlers.values()):
        raise TypeError("Handler values must be callable")
