def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    all_subclasses = []
    to_visit = [cls]
    while to_visit:
        parent = to_visit.pop()
        for child in parent.__subclasses__():
            if child not in all_subclasses:
                all_subclasses.append(child)
                to_visit.append(child)
    return all_subclasses
